1	package ociresources
2	
3	import (
4		"github.com/anthnel/devdesk/internal/config"
5		"github.com/anthnel/devdesk/internal/engine"
6		"github.com/anthnel/devdesk/internal/scan"
7		"github.com/anthnel/devdesk/internal/ui/shortcut"
8	)
9	
10	// What the selected row allows, computed once and read by both halves of
11	// the view: GetShortcuts to gray out, the handlers to refuse (Rule 130).
12	// Two computations for one question eventually stop agreeing, and the
13	// symptom is a grayed-out key that acts anyway.
14	
15	// The reasons, written once so the header, the footer and the tests cannot
16	// drift apart on the wording (Rule 129 — English US).
17	const (
18		reasonNoImage      = "No image selected"
19		reasonImageScanned = "This image is being scanned"
20		reasonNoRegistry   = "No registry selected"
21		reasonInsideGroup  = "These rows are discovered members — edit the group instead"
22		reasonNotAGroup    = "This entry is a registry, not a group"
23		reasonAtTopLevel   = "Already at the registry list"
24		reasonNoTags       = "No scan results for this tag yet"
25		reasonNoScanner    = "Nothing can scan an image — install Trivy, or check scan settings"
26	)
27	
28	// imageActions reports whether N, S and D apply to the selected image.
29	//
30	// One state for the three because they share one condition: a row that is not
31	// in the middle of a scan. A scan reads the image while a delete removes it,
32	// and launching from an image being scanned is the same race one step removed.
33	func (m Model) imageActions() shortcut.Availability {
34		img := m.getSelectedImage()
35		switch {
36		case img == nil:
37			return shortcut.Unavailable(reasonNoImage)
38		case m.scanningImage(img.Name()):
39			return shortcut.Unavailable(reasonImageScanned)
40		}
41		return shortcut.Availability{}
42	}
43	
44	// imageScan reports whether S applies to the selected image.
45	//
46	// It is imageActions plus one condition that belongs to S alone: scanning an
47	// *image* from a container means inspecting one the host engine holds, which
48	// needs that engine's socket mounted into Trivy. Rootless podman has none
49	// unless `podman system service` is running (§3.67), and that is knowable
50	// before the keypress — so it is greyed with its reason rather than attempted
51	// and failed (Rule 130).
52	//
53	// N and D do not consult it: launching and deleting go through the engine's
54	// CLI, not through a container, and greying them for a missing socket would
55	// refuse actions that work.
56	//
57	// Not knowing is not knowing it is a no: while deps is nil nothing has looked
58	// yet, and greying S out for three frames to un-grey it afterwards reads as a
59	// fault. Same reasoning as workspaces' scannerState.
60	func (m Model) imageScan() shortcut.Availability {
61		if act := m.imageActions(); !act.Enabled() {
62			return act
63		}
64		if m.deps == nil {
65			return shortcut.Availability{}
66		}
67		if !m.deps.CanScan(m.config.Scan.Categories, scan.TargetImage) {
68			return shortcut.Unavailable(reasonNoScanner)
69		}
70		if m.deps.Status(scan.ToolTrivy).Source != scan.ToolSourceContainer {
71			// A Trivy binary reads the image through the engine itself and needs
72			// no socket of its own.
73			return shortcut.Availability{}
74		}
75		// The server address goes through OptionsFromConfig rather than being read
76		// off the config: it is ignored unless the client-server checkbox is on,
77		// and a second reading of that rule is a second chance to get it wrong.
78		server := scan.OptionsFromConfig(m.config).TrivyServer
79		if reason := m.deps.ImageScanBlocked(engine.Current().Name, server); reason != "" {
80			return shortcut.Unavailable(reason)
81		}
82		return shortcut.Availability{}
83	}
84	
85	// imageOpen reports whether enter has an image to open the details of.
86	func (m Model) imageOpen() shortcut.Availability {
87		if m.getSelectedImage() == nil {
88			return shortcut.Unavailable(reasonNoImage)
89		}
90		return shortcut.Availability{}
91	}
92	
93	// registryEntryActions reports whether the four config actions apply.
94	//
95	// Inside a group the rows are cached members rather than config entries: there
96	// is nothing to edit, log into or remove, and nothing to add beside them.
97	func (m Model) registryEntryActions() shortcut.Availability {
98		if m.registryGroupSlug != "" {
99			return shortcut.Unavailable(reasonInsideGroup)
100		}
101		if m.getSelectedRegistry() == nil {
102			return shortcut.Unavailable(reasonNoRegistry)
103		}
104		return shortcut.Availability{}
105	}
106	
107	// registryCreate reports whether N applies. It differs from the three others in
108	// that it needs no selected row — only a list that accepts new entries.
109	func (m Model) registryCreate() shortcut.Availability {
110		if m.registryGroupSlug != "" {
111			return shortcut.Unavailable(reasonInsideGroup)
112		}
113		return shortcut.Availability{}
114	}
115	
116	// registryDrillIn reports whether → has a group to enter.
117	func (m Model) registryDrillIn() shortcut.Availability {
118		if m.registryGroupSlug != "" {
119			return shortcut.Unavailable(reasonInsideGroup)
120		}
121		reg := m.getSelectedRegistry()
122		if reg == nil || reg.Kind != config.KindGroup {
123			return shortcut.Unavailable(reasonNotAGroup)
124		}
125		return shortcut.Availability{}
126	}
127	
128	// registryDrillOut reports whether ← has a level to leave.
129	func (m Model) registryDrillOut() shortcut.Availability {
130		if m.registryGroupSlug == "" {
131			return shortcut.Unavailable(reasonAtTopLevel)
132		}
133		return shortcut.Availability{}
134	}
135	
136	// scanOptions is the one place this view assembles scan options: the context's
137	// settings, on the router's detection so a scan does not probe the machine
138	// again (§3.86).
139	func (m Model) scanOptions() scan.ScanOptions {
140		opts := scan.OptionsFromConfig(m.config)
141		opts.Detected = m.deps
142		return opts
143	}
144

